// Local Expo config plugin: DEMO release signing for the packaged APK (06_packaging_spec §2.2, step 94).
//
// `apps/mobile/android/` is regenerated by `expo prebuild` (F-21), so hand edits to
// `android/app/build.gradle` are not durable. This plugin re-applies one marked block at the end of
// that file on every prebuild (idempotent: the marker is checked first). The block:
// - reads the git-ignored `apps/mobile/signing/release-signing.properties` (created once by
//   `scripts/create-demo-keystore.sh`) and signs the release build type with the DEMO key;
// - when the file is missing, fails any release task fast, so no "release" APK is ever signed with
//   the public debug key the template uses (F-23);
// - never touches the debug build type: debug builds stay exactly as they are.
// The passwords never enter the generated tree: Gradle reads them from the properties file at build
// time.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '@dems-release-signing';

const SIGNING_BLOCK = `
// ${MARKER}: generated by apps/mobile/plugins/with-dems-release-signing.js (06_packaging_spec §2.2). DEMO key only.
def demsSigningFile = new File(projectRoot, "signing/release-signing.properties")
if (demsSigningFile.exists()) {
    def demsSigning = new Properties()
    demsSigningFile.withInputStream { demsSigning.load(it) }
    android.signingConfigs.create("demsRelease") {
        storeFile new File(projectRoot, demsSigning.getProperty("storeFile"))
        storeType demsSigning.getProperty("storeType", "pkcs12")
        storePassword demsSigning.getProperty("storePassword")
        keyAlias demsSigning.getProperty("keyAlias")
        keyPassword demsSigning.getProperty("keyPassword")
    }
    android.buildTypes.release.signingConfig android.signingConfigs.demsRelease
} else {
    gradle.taskGraph.whenReady { graph ->
        if (graph.allTasks.any { it.project == project && it.name.toLowerCase().contains("release") }) {
            throw new GradleException("DEMS: apps/mobile/signing/release-signing.properties is missing. Run apps/mobile/scripts/create-demo-keystore.sh (06_packaging_spec §2.2).")
        }
    }
}
`;

/** Appends the signing block once; a second run leaves the file unchanged. */
function applyDemsReleaseSigning(contents) {
  if (contents.includes(MARKER)) return contents;
  return `${contents.replace(/\s*$/, '\n')}${SIGNING_BLOCK}`;
}

function withDemsReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') {
      throw new Error('with-dems-release-signing: android/app/build.gradle is not Groovy; update the plugin.');
    }
    mod.modResults.contents = applyDemsReleaseSigning(mod.modResults.contents);
    return mod;
  });
}

module.exports = withDemsReleaseSigning;
module.exports.applyDemsReleaseSigning = applyDemsReleaseSigning;
module.exports.MARKER = MARKER;
